def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # Encourage stacks with lower average IDs, more available space, and less height
    # Apply logarithmic penalty to higher average IDs for better long-term efficiency
    if AVG == 0:
        avg_penalty = 0
    else:
        avg_penalty = 1 + (AVG - CUR) / (AVG + 1)
    priority = (SH + 1) * (AVG + 1) / (EMP + 1) + avg_penalty
